"""Build the review tables and source notes from the assistant's recorded assessments.
This formats judgments; it does not perform independent screening or validation.
"""
from pathlib import Path
import json,csv,re,hashlib,datetime
P=Path(__file__).resolve().parent
D={r['record_id']:r for r in json.loads((P/'discovery-records.json').read_text())}
E=[]
def add(sid,kind,purpose,reviewers,concepts,format_,missing,access,evaluation,limits,loc):
 E.append(dict(source_id=sid,source_type=kind,purpose=purpose,intended_reviewers=reviewers,concepts_and_criteria=concepts,answer_format_and_guidance=format_,missing_information=missing,accessibility_and_effort=access,evaluation_and_findings=evaluation,evidence_assessment=limits,evidence_locator=loc,author_review='pending'))
add('S01','Empirical audit and recommendations','Examine whether benchmark evidence supports capability claims.','Benchmark researchers; annotation performed by experts.','Phenomena, tasks, metrics, claims; content, convergent, discriminant and ecological validity.','Annotation scheme and eight recommendations with a checklist; asks for explicit links between claims and evidence.','Absence of a documented justification is an observation about reporting; it does not establish that no relevant capability exists.','Explanations and checklist aid review. No measured novice understanding or review duration in the inspected method/results.','29 expert reviewers examined 445 benchmarks. The audit finds gaps in construct definitions and validity evidence. These are observations in the sampled papers, not a trial of reviewer accessibility.','Assess sampling, annotation criteria and expert judgments; benchmark selection and interpretive coding constrain generalization. No MESA comparison.','Sections 2–5; annotation appendices; PDF pp. 1–11 and 16–29.')
add('S02','Empirical platform audit','Examine fairness and reliability of Chatbot Arena rankings.','Evaluation researchers, platform operators and users interpreting rankings.','Private testing, selective reporting, sampling, data access, contamination and unequal provider participation.','Analyses of platform practices followed by recommendations for disclosure, limits and sampling. No general review answer form.','Observed private tests and publication choices are different from claims about undisclosed tests. Inference is constrained by accessible platform data.','Explains how ranking practices affect interpretation; does not evaluate a reader training or questionnaire intervention.','Audits private variants and provider participation, including 27 Meta variants, and studies effects on reported rankings. Findings concern the observed Arena setting.','Platform specific, time dependent observational evidence. Recommendations do not show that proposed changes improve novice judgments.','Sections 3–9, PDF pp. 5–31; appendices document data and analyses.')
add('S03','Professional review model','Guide description and evaluation of psychological and educational tests.','Reviewers with expertise in psychological testing; national associations implementing test reviews.','Part A description; Part B rationale/documentation, materials, norms, reliability, validity, fair use and generated reports; final evaluation.','Forms with explanatory guidance and item dependent anchors; n/a and 0–4 ratings. Overall judgments require interpretation, not a mechanical average.','Separates n/a and absent evidence from inadequacy: for example section 6.4 has 0 = no information, 1 = inadequate. Read each anchor in context.','Definitions and guidance support trained reviewers. Test taker accessibility criteria are not evidence that the review model is accessible to novice reviewers.','Normative guidance drawing on prior test review practice. The 2025 model does not report an AI benchmark reviewer trial in the inspected text.','Assess authority, scope and transfer assumptions. Adaptation to AI is a research decision, not EFPA endorsement. The complete 90 page source includes forms and guidance.','Introduction PDF pp. 6–8; Parts A/B; section 6.4 PDF30, fair use sections; Part C PDF86–89.')
add('S04','Foundation standard (2014 exception)','Set standards for evidence supporting test score interpretations and uses.','Test developers, users, policymakers and measurement professionals.','Validity; reliability/precision; fairness; design, administration, reporting, documentation and use.','Standards with explanatory comments rather than a short checklist or one quality score.','Calls for evidence and disclosure of limitations; lack of supporting evidence limits interpretation. Does not prescribe MESA response choices.','Fair access and test taker rights concern assessment participants. They do not demonstrate accessibility of a benchmark review procedure.','Professional standards; not an experiment or an AI benchmark audit.','Authority and applicability assessed separately from empirical findings. Human test concepts require explicit transfer arguments when applied to AI.','Chapters 1–3, printed pp. 11–72; chapters 6–7, pp. 111–130; introductory scope.')
add('S05','Classification framework with application','Categorise AI evaluation instruments for comparing capabilities. Review unit: Chapter 6 within the volume.','AI evaluation researchers and instrument selectors; chapter describes student raters.','18 facets under Validity, Consistency and Fairness. These groups address what is measured, how it is measured and which system is measured.','Facet specific categorical values, explanations and examples. Some values express preferences; other facets categorise purposes without a universal preferred value.','Reliability allows N/A when methodology or common use is unclear. This is not identical to an explicit finding of poor reliability or inapplicability.','Definitions and an applied classification procedure; agreement difficulties reveal interpretation work. No measured reduction in novice effort or improvement in understanding.','36 instruments classified; initially four student raters, later two per instrument, with discussion and revisions. Capability, Coverage, Specificity, Adjustability and Ambition were among difficult facets.','Application and rater discussion provide evidence of use, not validation for general readers. Do not call the 18 facets a benchmark quality scale.','Chapter 6, printed pp. 99–118, especially pp. 100–110; PDF pp. 101–112. Table 6.1 and facet definitions pp. 101–102.')
add('S06','Conceptual proposal with model application','Define AGI through a profile of cognitive abilities and propose tests.','AI researchers and readers interpreting broad intelligence claims; assumes familiarity with cognitive assessment.','CHC inspired ten domain account; distinguishes broad ability from task performance. Operational thresholds and aggregate AGI score are authors’ proposal.','Definitions, testing notes, examples and domain thresholds. Not a general benchmark review checklist.','Insufficient coverage cannot justify a broad intelligence claim. This work does not supply MESA style missing evidence categories.','Examples explain domains; no measured accessibility of benchmark reviews in inspected sections.','Applies a proposed scoring framework to AI systems. Demonstrates the proposal, not consensus on a definition or validation of every task/domain mapping.','Assess justification for domains, weights, thresholds and transfer from human cognition. Do not import its aggregate AGI score as benchmark quality.','Sections 2–4 and appendices A–J; local PDF version v3, 57 pages; first public release 21 October 2025.')
add('S07','Review framework with benchmark audit','Assess benchmark construction, documentation, implementation and maintenance.','Benchmark developers, evaluators and model users.','46 criteria across development and application in the inspected PDFs; documentation, validity, reliability, reproducibility and usability of benchmarks.','Criterion specific rubrics using 0/5/10/15; examples and guidance; stakeholder interviews and assessment calibration.','Missing documentation can receive zero under particular rubrics. That documents evidence availability and does not establish every underlying practice was absent.','Benchmark usability includes implementation and documentation access. Stakeholder input is evidence of design consultation; it is not a controlled novice comprehension or time study.','Inspected local and proceedings PDFs report assessment of 24 benchmarks using 46 criteria. The proceedings landing abstract instead reports 25 benchmarks and 40 practices; retain this conflict.','Rubrics and author assessments support an audit, not proof of accessibility gains. Do not mix the landing abstract counts with the inspected PDF methods.','Sections 3–5; appendices with rubrics and interview questions; version-audit.md.')
add('R002','Conceptual framework','Decide when and how to retire benchmarks.','Developers, users and governance actors.','Suitability for purpose; full versus partial deprecation; saturation and failure to support claims.','Criteria and a deprecation process rather than a reviewer response scale.','Evidence for deprecation is contextual; high performance alone is not sufficient proof of uselessness.','Procedural guidance; no measured novice understanding or duration in the inspected text.','Proposes criteria based on benchmarking practice; no comparative reviewer trial reported.','Reasoning and examples support the proposal. Its use and thresholds need evaluation.','Sections 2–4; PDF pp. 1–8.')
add('R004','Review, tool and empirical applications','Organise software engineering benchmarks and improve selection and construction.','AI for software engineering researchers and practitioners.','BenchScout search; BenchFrame quality guidance; benchmark repair and testing.','Search interface, workflow and framework rather than a general categorical form.','Documents benchmark limitations and repair decisions; no dedicated unknown versus no response format established here.','22 participants rated tool usability, effectiveness and intuitiveness. Their mean familiarity was 3.8/5; 15/22 rated familiarity 4 or 5. This is a counterexample to no human evidence, but not a sample of beginners.','Reviews 247 studies and 273 benchmarks. User ratings 4.5, 4.0 and 4.1/5 are perceptions. Benchmark repair experiments concern changed benchmark outputs, not reviewer understanding.','Convenience sample, self reports and no controlled timed comparison. Separate the tool study from model evaluation of repaired benchmarks.','Sections IV-C and VII-E; PDF pp. 8–10 and threats to validity section.')
add('R042','Annotation audit and assistance method','Identify and repair annotation errors in reasoning datasets.','Dataset auditors with logic and annotation expertise.','Correctness, ambiguity, reference labels and targeted human relabeling.','Verification and prioritisation workflow with model assistance.','Distinguishes flawed formalization and ambiguity; detection is not proof all remaining labels are correct.','Reduction in instances requiring review is not measured reading time or novice accessibility.','Audits 275 FOLIO validation items and the first 100 MALLS items, with a 213 item control; reports errors and explores selective review.','Fixed sample and domain constrain generalization. Human labels and formal verification each have assumptions.','Sections 2–4; PDF pp. 2–12; limitations.')
add('R061','Conceptual framework','Organise evaluation across LLMs, agents and multimodal systems.','Researchers and evaluation practitioners.','Eight trustworthiness dimensions; validity, reliability and reproducibility of evaluation.','Dimensions, procedure and interpretation bands.','Reporting and uncertainty concerns are discussed; no independently validated missing evidence rule.','Guidance is proposed; no demonstrated novice benefit.','Conceptual synthesis; empirical validation is future work.','Do not report proposed bands as calibrated thresholds.','Sections III–VIII, especially future work/limitations PDF p. 11.')
add('R063','Appraisal framework and literature synthesis','Review methods used to evaluate LLMs in ophthalmology.','Researchers, journal reviewers and evidence reviewers in medicine.','20 items across Sample, Independence, Ground truth, Handling repeated/paired data and Transparency.','Yes/Partial/No or NR with 2/1/0 points and NA; item explanations and applicability rules.','No and not reported share a scoring category. Record this loss of distinction when comparing answer formats.','Detailed anchors can guide review, but length and anchors are not demonstrated accessibility.','Synthesises ophthalmology studies and proposes SIGHT. Limitations section describes the framework as requiring further validation.','Clinical scope, literature selection and unvalidated appraisal thresholds limit transfer to a general form.','Methods PDF p. 7; framework pp. 34–51; limitations pp. 52–53.')
add('R078','Empirical measurement method','Identify assessment items that behave differently for humans and chatbots.','Assessment designers with psychometric expertise.','Differential item functioning; item total relationships; negative controls.','Statistical diagnostics rather than reviewer categorical judgments.','Test design and diagnostic evidence are separate from missing documentation. No review missingness scale.','No review comprehension or effort evaluation in the inspected experiment.','Applies diagnostics to two tests and six chatbots, examining item functioning and human comparisons.','Specific tests and models constrain transfer; model scores are not human reviewer responses.','Sections 3–5, PDF pp. 3–6.')
add('R091','Empirical evidence audit','Assess whether incident records support assurance benchmark construction.','Security and assurance benchmark researchers.','Reconstruction, replay, oracle feasibility, pairing, release conditions and provenance.','A registry and evidence classification; explicit unresolved alternatives.','Distinguishes inaccessible evidence, failure of qualification and uncertainty about authored semantics.','Traceability supports inspection; no reviewer accessibility measurement reported in inspected method/discussion.','40 incidents: 39 had patches/corrected states but 20 met strict pairing criteria. Ten case provenance audit; alternative assumptions changed a case conclusion.','Selected incident frame, authored representations and task relative criteria; does not estimate population readiness or detector accuracy.','HTML full text sections 1, 3–6; abstract; source request log.')
add('R097','Scorecard with case applications','Judge benchmark suitability for different uses.','Developers and third party assessors with varying backgrounds.','Construct, internal and external validity, reliability and correctness.','Satisfied/unsatisfied/NA with reasons; dimension scores 1–4 and suitability categories.','Vague or absent documentation can count as nonfulfilment. This differs from preserving an unknown response.','Guidance and explanations exist. Two assessors disagreed on six items for Vending-Bench 2; no measured novice comprehension or time.','Case applications include ImpossibleBench and Vending-Bench 2; disagreement concerned item scope and evidential weight. Thresholds explicitly not empirically validated.','Direct counterexample to absence of review tools or reviewer evidence. Small assessor study cannot establish use across expertise levels.','Sections 3–7, printed pp. 130–135; appendices A–D.')
add('R257','Review','Synthesize concerns about AI benchmarking.','Researchers, policymakers and evaluators.','Nine issue areas spanning data, design, use and social incentives; validity and reporting.','Narrative synthesis and recommendations, not one scored reviewer form.','Distinguishes unknowns and reporting gaps from empirical demonstrations across underlying studies.','No direct evaluation of novice reviewer use in this review.','Meta review of about 110 studies over ten years. Its older evidence is not separately counted as included recent studies in this SLR.','A review is a map of claims, not an independent replication of each underlying experiment.','Introduction, review method, issue sections and conclusion; AIES 2025 PDF pp. 1–15.')
add('R259','Review','Compare agent evaluation with requirements of deployment.','Agent researchers and practitioners.','Task success versus cost, safety, workflow fit, maintainability and deployment.','Taxonomy and guidance; comparisons of 15 agent benchmarks.','Reporting limits constrain what benchmark scores justify. No standard unknown response format.','No direct novice review study in inspected synthesis and limitations.','Literature synthesis identifies mismatches between benchmark success and deployment concerns.','Selection and domain coverage limit conclusions; recommendations are not measured improvements.','HTML full text: review methodology, benchmark analysis, challenges and conclusion.')
add('R286','Database and search tool','Support discovery of benchmarks and evaluation results.','Researchers and benchmark users.','Source preserving retrieval, benchmark metadata and results.','Search interface and structured records.','Retains provenance; search output alone is not verification of quality.','Addresses finding and accessing information. Retrieval precision, task suitability and time saved are not established by a controlled user study.','Database reports 1,283 benchmark records and 12,916 observations; examples illustrate retrieval.','Corpus coverage and retrieval claims need separate assessment. No evidence that a search hit improves reviewer understanding.','Sections 3–6; limitations PDF pp. 12–13.')
add('R291','Empirical benchmark validity audit','Test whether benchmark score patterns support intended constructs.','Researchers using psychometrics and benchmark results.','Convergent/discriminant validity and item response theory.','Statistical analysis, not a review questionnaire.','Unclear construct definitions limit interpretation; correlations alone do not identify causes.','No reviewer accessibility intervention.','Analyses 56 benchmarks and 53 models; reports weaknesses in convergence and separation of some intended concepts.','Models, benchmark coverage and general ability confounding constrain interpretation.','Methods/results; discussion and limitations PDF pp. 10–11.')
add('R296','Benchmark audit and curated evaluation','Examine errors hidden by aggregate benchmark scores.','Benchmark researchers and model evaluators.','Reliability as consistently correct performance on curated tasks; annotation correctness.','Curated platinum subsets and error analysis.','Unexamined items may retain errors; agreement across models does not establish a correct reference answer.','No reader accessibility test.','Builds 15 curated benchmark subsets and examines model errors even on tasks expected to be straightforward.','Small subsets and selection around observed errors can miss shared failures; reliability here differs from OECD test retest variance.','Sections 2–5 and appendices; limitations section.')
add('R306','Survey','Map LLM benchmarks and design concerns.','Benchmark researchers and users.','Capabilities, knowledge, domain proficiency, safety and benchmark design.','Taxonomy and design recommendations.','Coverage gaps are relative to survey scope; no categorical missing evidence rule for reviewers.','Information organisation rather than measured reader improvement.','Surveys 283 benchmarks and proposes directions for design.','Selection and fast changing landscape limit coverage; not a validation study of a review form.','Sections 2–5; conclusion PDF p. 34.')
add('R310','Survey','Explain benchmark contamination detection and mitigation.','LLM evaluators with technical expertise.','Matching, comparison, contamination effects and benchmark alternatives.','Taxonomy of detection and mitigation approaches.','Failure to detect overlap is not proof of no contamination; lack of training data access constrains claims.','Explanations are available; no direct reviewer effort measurement.','Compares detection approaches and their assumptions; synthesises evidence rather than a human study.','Detector performance depends on access and contamination definition.','Sections 2–5, especially detection sections 3.1–3.2 and mitigation section 4.')
add('R321','Empirical statistical method','Improve correspondence between benchmark scores and pairwise preferences.','Evaluation researchers with statistical expertise.','Item weighting and preference alignment.','Learned weights and comparisons, not a human review form.','Unobserved preferences and distribution changes limit inference.','No demonstrated novice review accessibility.','Analyses 4,576 models across six benchmarks with preference based reweighting.','Improved correspondence on available data is not universal validity or correctness of human preferences.','Section 4 and limitations section 5, PDF pp. 5–10.')
add('R349','Reporting checklist','Guide reporting of generative AI evaluation in medicine.','Medical researchers and reviewers.','Questions, models, prompts, scoring, analysis and reporting.','Inspected preprint contains 23 items with explanations; later journal record reports 32.','Reporting omissions are review concerns, not direct evidence of model failure.','Explanations provide guidance; no measured novice comprehension in inspected preprint.','A checklist proposal. Do not combine the 23 item preprint with the 32 item publication.','Final publication full text was blocked; evidence extraction here is explicitly for the accessible preprint.','Preprint tables 1–2 and discussion; version-audit.md.')
add('R357','Empirical reviewer study','Evaluate agreement when applying QUADAS-2 to AI imaging studies.','Five dental reviewers with prior QUADAS-2 experience; repeated ChatGPT-4o runs.','Risk of bias and applicability; categorical agreement.','Low/high/unclear risk at seven domain judgments per study.','Unclear is distinct from high risk. Agreement does not establish correct judgments.','Evidence of actual reviewer use, but not novice accessibility or measured time savings.','20 studies, five human reviewers and five runs of one model. Human kappa ranged −0.07 to 0.22; model values −0.17 to 0.56. No calibration; pragmatic sampling.','Model runs are not independent people. Category prevalence affects kappa. Authors note sample, lack of calibration and unrecorded exact model session dates.','HTML Materials and Methods, Results and Discussion.')
add('R362','Reporting framework, interviews and corpus audit','Present evaluation information for different readers.','Technical evaluators, AI engineers, policy actors and general readers.','Provenance, reproducibility, reporting completeness and comparability.','Structured evaluation cards; summary and research modes; plain language caveats and missing field signals.','Explicit missing reporting signals; documentation completeness is different from the validity of a claim.','Stakeholder interviews and feedback support design. Quotes about time savings are perceptions, not timed task results; systematic usability work is planned.','Same PDF reports 10 interviews/101,843 results in abstract and 12/101,955 in body. Use neither pair as a settled denominator without resolving the conflict.','Strong counterexample to claims that no audience tailored interpretation tools exist. Corpus counts and interview denominators require author confirmation.','Sections 3–5, especially 4.3 PDF pp. 7–8; appendix B; version-audit.md.')
add('R383','Metadata specification with implementation experiments','Make evaluation tasks reproducible through machine readable descriptions.','Benchmark maintainers, researchers and tool/agent developers.','Task specifications, datasets, scoring, metadata and reproducibility.','Declarative task descriptions extending Croissant; implementations and agent experiments.','Missing implementation details constrain reproduction. Machine readable metadata does not ensure valid measurement.','Reduces some implementation barriers by design; agent performance is not evidence of human review effort reduction.','Specification with reproduction examples and automated experiments.','Coverage of tasks and tools limits generality; adoption and documentation remain requirements.','Sections 3–5, limitations PDF p. 9.')
add('B01','Conceptual position','Develop an evaluation science for generative AI.','Researchers, institutions and policymakers.','Real world relevance, iterative refinement and evaluation institutions.','Three lessons from safety and measurement practice with proposed actions.','Uncertainty about deployment cannot be resolved by a benchmark score alone.','No comparative reader study.','Argument drawing lessons from other fields; recommendations are not observed intervention effects.','Transfer from other industries requires testing and institutional context.','Sections 1–4, PDF pp. 2–8.')
add('B02','Practice report with examples','Codify reproducible language model evaluation.','Researchers and engineers implementing evaluations.','Prompt format, scoring, implementation choices, uncertainty and reproducibility.','Concrete examples and recommendations from evaluation harness development.','Insufficient setup disclosure prevents comparison or reproduction; successful execution is not a validity judgment.','Explains technical choices; no measured novice review understanding.','Draws on three years of harness development and examples of evaluation failures.','Experience based evidence is not a representative survey of all benchmarks.','Main sections on evaluation challenges and recommendations; appendices, 31 page PDF.')
add('B03','Design framework and case studies','Make benchmark design choices and their evidential support explicit.','NLP benchmark designers and analysts.','Five modules: capability, task, data, assembly and evidence; describe, justify and support.','20 question worksheet with guidance; applied to BoolQ, SuperGLUE and HELM.','Separates describing a choice from justifying it and supplying evidence. Paper only analysis cannot establish absence from websites or code.','A concise worksheet already exists. User studies of understanding and utility are explicitly future work.','Three author case analyses identify description without adequate justification or validity evidence.','Only three benchmarks and their papers; author interpretation; validity scope omits other concerns such as privacy and reliability.','Sections 3–5, worksheet appendix; Limitations printed pp. 16357–16358.')
add('B04','Review and conceptual analysis','Discuss inadequacies in LLM benchmark practice.','Researchers and evaluators.','Coverage, robustness, fairness, interpretability and mismatch with uses.','Synthesis and proposed directions; not a validated review form.','Unreported or unmeasured aspects limit interpretation.','No reviewer comprehension or effort study in inspected discussion.','Analyses benchmarking problems and argues for broader evaluation approaches.','Review conclusions depend on source selection and conceptual reasoning; no comparative form trial.','Introduction, framework discussion and conclusion; accessible arXiv version.')
add('B05','Statistical methods guidance','Quantify uncertainty in evaluation results.','Researchers with some training in statistics, explicitly stated.','Sampling, standard errors, paired comparisons, clustering and experiment planning.','Equations, worked examples and reporting recommendations.','A missing interval does not quantify uncertainty; significance does not establish substantive validity.','Examples support readers with statistical training; no observed novice benefit.','Derives analysis guidance and uses hypothetical examples; these are not a reviewer experiment.','Inference depends on sampling assumptions and the target population of tasks.','Sections 1–6; hypothetical example explicitly labelled, PDF pp. 1–14.')
add('B06','Statistical framework','Estimate capabilities and uncertainty for nested evaluations.','Researchers with statistical/modeling expertise.','Hierarchical Bayesian GLMs, partial pooling and model comparison.','Worked examples and software package.','Uncertainty is modeled rather than replaced by a point score; assumptions remain part of the evidence.','Implementation guidance; no novice reviewer study.','Illustrative applications and method comparisons demonstrate statistical inference.','Results depend on priors, hierarchy and model fit; not a validation of benchmark construct meaning.','Sections 2–5 and examples; 23 page PDF.')
add('B07','Position with proof of concept experiments','Test construct validity of medical LLM benchmarks.','Medical AI and measurement researchers.','Claimed clinical ability versus exam performance; validity evidence.','Argument and empirical validation examples using clinical data.','Missing clinical evidence does not establish clinical competence.','No benchmark review accessibility trial.','Reviews evaluation use in 100 cited medical LLM papers and illustrates construct validity tests with clinical data.','Proof of concept and chosen tasks do not generalise to all clinical applications.','Sections 2–4 and limitations; PDF pp. 1–8.')
# Additional citation studies. Claims remain confined to the inspected methods/results/discussion.
more=[
('B08','Conceptual framework','Classify progress toward AGI.','Performance, generality and autonomy; six principles and levels.','Definitions and levels with benchmark requirements.','Levels are a proposal, not consensus or validated score interpretation.','Sections 2–7; PDF pp. 2–9.'),
('B09','Empirical meta analysis','Examine whether safety benchmarks distinguish safety from general capability.','Correlations with capability and training compute.','Analyses across models and recommendations for separating safety from capability.','Correlation does not identify causation; chosen operational definitions and models constrain interpretation.','Methods section 3, benchmark analyses, discussion section 7.'),
('B10','Empirical measurement framework','Explain and predict performance through demand and ability profiles.','18 rubrics; 15 models and 63 tasks in the reported application.','Automated rubric annotation and prediction analysis.','LLM annotations and choice of tasks constrain interpretation; predictive fit does not settle construct validity.','Sections 2–4 and Methods 6, PDF pp. 5–20 and 27–34.'),
('B11','Empirical sensitivity study','Test dependence of evaluations on instruction wording.','Prompt variation; absolute performance and model ranking.','Experiments with 20 models, 39 tasks and 6.5 million instances; multi prompt metrics.','Sampling of paraphrases and tasks limits generality; best prompt and average prompt answer different questions.','Sections 3–7 and conclusion 9, PDF pp. 3–12.'),
('B12','Empirical sensitivity study','Examine leaderboard changes under evaluation perturbations.','Answer order, prompt and scoring decisions.','Controlled perturbations of multiple choice evaluation; reports rank changes up to eight places.','Limited benchmark and model coverage; proposed mitigations do not remove all sensitivity.','Methods section 3; experiments/results 4–5; limitations 8.'),
('B13','Empirical contamination study','Show how benchmark exposure changes evaluation results.','Benchmark leakage and fair model comparison.','Training/evaluation experiments and guidelines for developers and benchmark maintainers.','Artificial exposure settings do not measure contamination of every released model.','Sections 2–4, PDF pp. 3–8.'),
('B14','Empirical contamination study','Test whether string matching detects transformed test data.','Paraphrase/translation leakage; decontamination.','Experiments on benchmark transformations and detection methods.','Synthetic contamination demonstrates vulnerability, not universal prevalence; detection remains imperfect.','Sections 3–6, especially experiments 5 and discussion 6.'),
('B15','Empirical annotation sensitivity study','Examine effects of unreliable preference votes.','Apathetic, adversarial and variable judgments in open leaderboards.','Simulation and analysis of poor quality votes; 10 percent can move rankings by up to five places in studied conditions.','The simulated votes are not an estimate of actual bad vote prevalence; disagreement can reflect legitimate preferences.','Section 3 analyses; conclusion 4 and limitations PDF pp. 5–6.'),
('B16','Empirical adversarial analysis','Test vulnerability of voting based leaderboards.','Model identification, vote manipulation and mitigations.','Offline simulations and proposed/implemented defenses with platform developers.','Simulations establish a vulnerability under assumptions, not proof of real vote manipulation at that frequency.','Attack and defense sections; abstract identifies offline simulation.'),
('B17','Empirical cultural bias audit and benchmark resource','Examine cultural and translation effects in multilingual evaluation.','Cultural sensitivity, geographic coverage and translation artifacts.','Question annotation and cross language/model comparisons.','Dataset corrections and translations do not establish culture neutral measurement; local annotation judgments matter.','Sections 3–5; limitations 7, PDF p. 24.'),
('B18','Review and conceptual analysis','Clarify what AI red teaming evaluates and how.','Purpose, artifact, actors/resources, methods and decisions.','Survey and coding of practices; separates different kinds of risk and approach.','Taxonomy is not a validated reviewer tool; disclosure and selection constrain the review.','Methods and analysis sections 2–4, especially 4.2–4.3.'),
('B19','Empirical contamination study','Isolate effects of exposure during pretraining.','Text versus ground truth contamination and repetition.','GPT-2 training experiments and critique of n-gram detection.','Scale and controlled corpora constrain transfer to current hosted models.','Experimental setup 3 and analyses 4, PDF pp. 3–8.'),
('B20','Empirical contamination measurement method','Assess contamination metrics by their relation to score inflation.','ConTAM; metric thresholds, tasks and model effects.','13 benchmarks and seven models from two families; comparison of contamination measures.','Thresholds and model size interact; one global overlap cutoff is not sufficient.','Methods 3–4; results 5–6; discussion 8, PDF p. 17.'),
('B21','Empirical latent capability analysis','Model structure in benchmark performance.','Latent capabilities, confounding and causal assumptions.','Over 1,500 models across six benchmarks; causal representation model.','Causal conclusions depend on structural assumptions and base model control; not evidence that all constructs are distinct.','Framework sections and experimental results 4; discussion 5, PDF pp. 9–11.'),
('B22','Historical and sociological analysis','Explain how benchmarking shapes research priorities.','Institutional incentives, measurable progress and research concentration.','Interviews and computational/historical analyses.','Historical interpretation and interview sampling do not establish a reviewer intervention effect.','Methods 3, historical analysis 4–6 and discussion 7.'),
('B23','Empirical adversarial analysis','Assess sensitivity of Arena ranks to vote rigging.','Elo interactions and target model rankings.','Experiments on about 1.7 million historical votes; simulated added votes.','Historical/offline attacks show possibilities under assumptions, not actual misconduct rates.','Attack methods and evaluation sections; conclusion 9.'),
('B24','Empirical sensitivity study','Test whether model cognitive behavior depends on prompts and temperature.','Horizon task; exploration/exploitation and querying conditions.','Experiments with three OpenAI models and changed prompts/settings.','One psychological task and model family; resemblance to human behavior does not establish human equivalence.','Experiments 3; discussion/conclusion and limitations 4–5, PDF pp. 2–5.'),
('B25','Empirical adversarial analysis','Test robustness of LLM judges to answer manipulation.','Absolute versus comparative scoring and transferable attack text.','Surrogate attack experiments and transfer to other judges.','Attacks depend on judge, task and setup; robustness checks are not evidence of human reviewer behavior.','Experimental setup 5; results 6; conclusions/limitations 7–8, PDF pp. 4–9.')]
for sid,kind,purpose,concepts,ev,lim,loc in more:
 add(sid,kind,purpose,'AI evaluation researchers; technical knowledge is assumed by the method.',concepts,'Method, definitions or recommendations as described in the evaluation field; no general categorical benchmark review questionnaire.','No shared missing information response scale. Report unavailable evidence separately from the observed experimental finding.','No measured novice benchmark review understanding or effort identified in the inspected method/results. This is not a claim about every possible use of the work.',ev,lim,loc)
(P/'extraction.json').write_text(json.dumps(E,ensure_ascii=False,indent=2)+'\n')
print('Extraction records',len(E))
